import static org.junit.Assert.assertNotNull;

public class BasePeriod_toDurationTo_TriageGen0Test {

    @Test
    public void testToDurationTo_StandardPeriod() {
        // Create a period of 1 day
        DateTime start = new DateTime(2023, 1, 1, 0, 0, 0, 0);
        DateTime end = new DateTime(2023, 1, 2, 0, 0, 0, 0);

        // BasePeriod is protected, so we use a concrete subclass or common implementation via Period
        // Since the target is BasePeriod, we use Period which extends BasePeriod
        Period period = new Period(0, 0, 0, 1, 0, 0, 0, 0, PeriodType.dayBased(), Chronology.getStandardChronology());

        // We need to simulate the behavior where 'this' is a period added to endInstant
        // The method calculates: startMillis = chrono.add(this, endMillis, -1)
        // If period is 1 day, and end is Jan 2, start should be Jan 1.

        Duration result = period.toDurationTo(end);

        assertNotNull(result);
        long expectedMillis = end.getMillis() - period.getDuration().getMillis();
        assertEquals("Duration millis should match the interval between end and start", 
                period.getDuration().getMillis(), result.getMillis());
    }

    @Test
    public void testToDurationTo_WithDifferentChronology() {
        // Test with ISO chronology explicitly
        Chronology isoChrono = Chronology.getStandardChronology();
        DateTime end = new DateTime(2023, 12, 31, 23, 59, 59, 0);

        // A period of 1 hour
        Period hourPeriod = new Period(0, 0, 0, 0, 1, 0, 0, 0, PeriodType.hourBased(), isoChrono);

        Duration result = hourPeriod.toDurationTo(end);

        assertNotNull(result);
        // 1 hour = 3600000ms
        assertEquals(3600000L, result.getMillis());
    }

    @Test
    public void testToDurationTo_ZeroPeriod() {
        DateTime end = new DateTime();
        Period zeroPeriod = new Period(0, 0, 0, 0, 0, 0, 0, 0, PeriodType.dayBased(), Chronology.getStandardChronology());

        Duration result = zeroPeriod.toDurationTo(end);

        assertNotNull(result);
        assertEquals(0L, result.getMillis());
    }

    @Test
    public void testToDurationTo_LargePeriod() {
        // Test with a large period (e.g., 1 year) to ensure chrono.add handles large shifts
        DateTime end = new DateTime(2025, 1, 1, 0, 0, 0, 0);
        Period yearPeriod = new Period(1, 0, 0, 0, 0, 0, 0, 0, PeriodType.yearBased(), Chronology.getStandardChronology());

        Duration result = yearPeriod.toDurationTo(end);

        assertNotNull(result);
        // The duration returned should represent the length of the period defined
        // Note: toDurationTo returns a Duration object which is millisecond based.
        // For year-based periods, the duration is the number of millis in that specific year period.
        long expectedMillis = end.minusYears(1).getMillis();
        long actualMillis = end.getMillis() - result.getStartMillis();

        // Verify that adding the duration to the start results in the end
        // Or more directly, check if the duration matches the period's millisecond length
        assertEquals(yearPeriod.getDuration().getMillis(), result.getMillis());
    }

    @Test
    public void testToDurationTo_MillisPrecision() {
        DateTime end = new DateTime(2023, 5, 5, 10, 10, 10, 500);
        // Period of 500 millis
        Period millisPeriod = new Period(0, 0, 0, 0, 0, 0, 0, 500, PeriodType.millisBased(), Chronology.getStandardChronology());

        Duration result = millisPeriod.toDurationTo(end);

        assertEquals(500L, result.getMillis());
        assertEquals(end.getMillis() - 500L, result.getStartMillis());
    }
}

/**
 * Helper class to allow testing of the protected BasePeriod 
 * via the concrete Period implementation.
 */
class Period extends BasePeriod {
    protected Period(int years, int months, int weeks, int days, int hours, int minutes, int seconds, int millis, PeriodType type, Chronology chrono) {
        super(years, months, weeks, days, hours, minutes, seconds, millis, type, chrono);
    }
}
